 function textPlane(text,width,height,color,bg,pos,parent=room){const cn=document.createElement('canvas');cn.width=512;cn.height=256;const ctx=cn.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,512,256);ctx.fillStyle=color;ctx.textAlign='center';ctx.font='bold 49px Georgia';ctx.fillText(text,256,142);const tex=new T.CanvasTexture(cn);tex.colorSpace=T.SRGBColorSpace;return mesh(new T.PlaneGeometry(width,height),new T.MeshStandardMaterial({map:tex,roughness:1}),pos,[1,1,1],parent)}
 scene.add(new T.HemisphereLight('#fff9e5','#b5b49b',2.5));const sun=new T.DirectionalLight('#fff0c9',3.1);sun.position.set(-3,8,4);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);Object.assign(sun.shadow.camera,{left:-8,right:8,top:8,bottom:-8,near:.1,far:25});sun.shadow.normalBias=.035;sun.shadow.bias=-.0002;scene.add(sun);const fill=new T.DirectionalLight('#e9eee0',1.1);fill.position.set(6,4,-3);scene.add(fill);
