 const backMat=mat('#e6e4ce',{transparent:true}),leftMat=mat('#d9dfc7',{transparent:true});const back=box([11,4.7,.18],backMat,[0,2.25,-4.42]),left=box([.18,4.7,9],leftMat,[-5.5,2.25,0]);
