 for(const x of[-1.98,1.98]){const curtain=box([.46,2.65,.13],'#efe7ce',[x,.05,.3],windowGroup);curtain.rotation.z=x<0?-.035:.035;for(let j=0;j<4;j++)cylinder(.035,.035,2.6,'#e4dcc1',[x-.15+j*.1,.05,.38],windowGroup)}box([4.8,.075,.075],'#b6b295',[0,1.47,.28],windowGroup);
 // Sage sofa, soft cushions, feet, and a café table.
 const sofa=new T.Group();sofa.position.set(2.75,0,-2.45);room.add(sofa);for(const x of[-1.15,1.15])for(const z of[-.44,.45])cylinder(.065,.055,.36,'#957c5e',[x,.18,z],sofa);box([3,.55,1.35],'#9eaf86',[0,.6,0],sofa);box([3,1.15,.28],'#b5c39d',[0,1.3,-.57],sofa);for(const x of[-1.46,1.46]){const arm=box([.32,.65,1.45],'#afbe96',[x,.99,.02],sofa);arm.geometry.computeVertexNormals()}for(const x of[-.73,.73])box([1.35,.19,1.13],'#c1cba8',[x,.93,.05],sofa);const cushion=ball([.43,.39,.14],'#ecdfc4',[-.88,1.37,-.25],sofa);cushion.rotation.z=-.17;ball([.4,.34,.15],'#cda991',[.9,1.33,-.22],sofa);
 cylinder(.65,.68,.12,'#c2a17b',[3,.86,.15]);cylinder(.065,.095,.82,'#a68b66',[3,.42,.15]);cylinder(.4,.4,.055,'#a68b66',[3,.04,.15]);cylinder(.11,.1,.2,'#f1e7d0',[3,.99,.13]);mesh(new T.TorusGeometry(.085,.018,8,24),'#f1e7d0',[3.13,1,.13]);
 function plant(x,z,scale=1){const group=new T.Group();group.position.set(x,0,z);group.scale.setScalar(scale);room.add(group);cylinder(.32,.23,.55,'#c59d80',[0,.3,0],group);cylinder(.34,.34,.08,'#d4b395',[0,.6,0],group);cylinder(.27,.27,.025,'#8d765a',[0,.645,0],group);tube([[0,.6,0],[0,1.1,0],[.05,1.9,.02]],.025,'#7b8c61',group);for(let j=0;j<7;j++){const a=j*2.3,y=.85+j*.15;const leaf=ball([.28,.11,.13],j%2?'#8d9f72':'#a8b888',[Math.cos(a)*.2,y,Math.sin(a)*.18],group);leaf.rotation.z=Math.cos(a)*.5;leaf.rotation.y=-a}return group}
 plant(-4.35,-2.5,1.3);plant(4.6,-3.5,.95);plant(-4.5,2.5,.7);
 // Low bookshelf and a framed café print along the green wall.
 const shelf=new T.Group();shelf.position.set(-4.75,.1,.15);shelf.rotation.y=Math.PI/2;room.add(shelf);for(const y of[.1,.85,1.6])box([2.1,.12,.6],'#c1a37f',[0,y,0],shelf);for(const x of[-1,1])box([.1,1.6,.6],'#c1a37f',[x,.83,0],shelf);for(let i=0;i<7;i++){const book=box([.16,.48,.35],['#99aa87','#d3ac94','#d8ccaa','#a4b4b1'][i%4],[-.8+i*.22,.39,.03],shelf);book.rotation.z=i===4?-.14:0}cylinder(.13,.1,.22,'#eee3c9',[-.5,1.78,0],shelf);ball([.13,.13,.13],'#9eae7d',[-.5,1.96,0],shelf);
 const print=new T.Group();print.position.set(3.1,3.15,-4.25);room.add(print);box([1.38,1.65,.08],'#b99d79',[0,0,0],print);box([1.2,1.47,.04],'#f6efdd',[0,0,.055],print);textPlane('little paws',.98,.49,'#7f8d6b','#f6efdd',[0,-.43,.085],print);ball([.28,.29,.015],'#a6b58d',[0,.17,.09],print);for(let i=0;i<4;i++)ball([.09,.12,.015],'#a6b58d',[(i-1.5)*.16,.48+(i===1||i===2?.08:0),.1],print);
 // A woven rug, food bowl, yarn, and scratching post.
 const rug=cylinder(1.9,1.9,.045,'#d9bda0',[0,.02,.6]);rug.scale.z=.78;for(const r of[1.64,1.76,1.85]){const ring=mesh(new T.TorusGeometry(r,.012,5,96),'#c5a78a',[0,.05,.6]);ring.rotation.x=Math.PI/2;ring.scale.y=.78}cylinder(.34,.28,.16,'#91aaa0',[-1.8,.12,1.2]);cylinder(.28,.28,.025,'#c7b58c',[-1.8,.21,1.2]);for(let i=0;i<12;i++)ball([.035,.028,.035],'#a17c55',[-1.8+Math.sin(i*2)*.19,.23,1.2+Math.cos(i*3)*.18]);ball([.19,.19,.19],'#c9967e',[1.65,.2,1.5]);for(let i=0;i<5;i++){const ring=mesh(new T.TorusGeometry(.193,.008,5,40),'#e4b8a1',[1.65,.2,1.5]);ring.rotation.set(i*.7,i*.9,i*.4)}tube([[1.7,.05,1.6],[2,.05,1.9],[2.5,.05,1.7]],.012,'#c9967e');cylinder(.52,.52,.09,'#c7ad87',[-2.5,.07,-1.45]);cylinder(.13,.13,1.3,'#c8b68c',[-2.5,.73,-1.45]);for(let i=0;i<14;i++){const ring=mesh(new T.TorusGeometry(.136,.009,4,24),'#af9c76',[-2.5,.18+i*.085,-1.45]);ring.rotation.x=Math.PI/2}ball([.2,.09,.2],'#a6b18a',[-2.5,1.42,-1.45]);
 // Cat model: round clay forms with features that remain dimensional when orbiting.
 const CAT_SCALE=.86;const catRoot=new T.Group();catRoot.scale.setScalar(CAT_SCALE);catRoot.position.set(0,.08,.65);room.add(catRoot);let head,tail,eyes=[],ears=[],petMeshes=[],accessories=[];
 function rebuild(c){catRoot.traverse(o=>o.geometry?.dispose());catRoot.clear();petMeshes=[];const model=buildCafeCat(T,catRoot,c);head=model.head;tail=model.tail;eyes=model.eyes;ears=model.ears;catRoot.traverse(o=>{if(o.isMesh)petMeshes.push(o)});currentCat={...c};catKey=[c.coat,c.accessory,c.sick].join('|');}

 function sync(c){const key=[c.coat,c.accessory,c.sick].join('|');if(key!==catKey)rebuild(c);currentCat={...c}}
 function setCamera(){const portrait=canvas.clientWidth<650;const r=distance*(portrait?1.12:1);camera.position.set(Math.sin(yaw)*Math.cos(pitch)*r,target.y+Math.sin(pitch)*r,Math.cos(yaw)*Math.cos(pitch)*r+target.z);camera.lookAt(target);camera.updateMatrixWorld();canvas.dataset.viewYaw=yaw.toFixed(3);canvas.dataset.viewPitch=pitch.toFixed(3)}
 function resize(){const w=canvas.clientWidth,h=canvas.clientHeight;renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix();setCamera()}
 const ro=new ResizeObserver(resize);ro.observe(canvas);
 function catAt(e){const r=canvas.getBoundingClientRect();pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);ray.setFromCamera(pointer,camera);return ray.intersectObjects(petMeshes,false).length>0}
 function stroke(e,previous){if(!previous)return;const dy=e.clientY-previous.y,dx=e.clientX-previous.x;if(Math.abs(dy)<1||Math.abs(dx)>Math.abs(dy)*2.5)return;const direction=Math.sign(dy);if(strokeDirection&&direction!==strokeDirection)reversals++;strokeDirection=direction;strokeDistance+=Math.abs(dy);if(strokeDistance>12){petUntil=performance.now()+1400;startPurr()}if(strokeDistance>=42){strokeDistance=0;reversals=0;if(performance.now()-lastReward>1100){lastReward=performance.now();canvas.dataset.petStrokes=String(+(canvas.dataset.petStrokes||0)+1);onStroke();}}}
 canvas.addEventListener('pointerdown',e=>{if(e.button>0||drag)return;unlockAudio();const pet=catAt(e);drag={id:e.pointerId,x:e.clientX,y:e.clientY,pet,moved:0};strokeDistance=0;reversals=0;strokeDirection=0;hover={x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);canvas.classList.toggle('orbiting',!pet)});
 canvas.addEventListener('pointermove',e=>{if(drag&&drag.id!==e.pointerId)return;const hit=catAt(e);canvas.classList.toggle('over-cat',hit);if(drag){const dx=e.clientX-drag.x,dy=e.clientY-drag.y;drag.moved+=Math.hypot(dx,dy);if(drag.pet)stroke(e,{x:drag.x,y:drag.y});else{wantedYaw-=dx*.006;wantedPitch=Math.max(.12,Math.min(1.02,wantedPitch+dy*.004))}drag.x=e.clientX;drag.y=e.clientY}else if(e.pointerType==='mouse'&&hit)stroke(e,hover);else{strokeDistance=0;reversals=0;strokeDirection=0}hover={x:e.clientX,y:e.clientY}});
 function end(e){if(drag?.id!==e.pointerId)return;if(e.type!=='pointercancel'&&drag.pet&&drag.moved<7){petUntil=performance.now()+1600;startPurr();onStroke()}drag=null;canvas.classList.remove('orbiting');if(canvas.hasPointerCapture(e.pointerId))canvas.releasePointerCapture(e.pointerId)}canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('lostpointercapture',()=>{drag=null;canvas.classList.remove('orbiting')});canvas.addEventListener('pointerleave',()=>{hover=null;strokeDistance=0;reversals=0});
 canvas.addEventListener('wheel',e=>{e.preventDefault();wantedDistance=Math.max(7.7,Math.min(18,wantedDistance+e.deltaY*.008))},{passive:false});canvas.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Home'].includes(e.key))return;e.preventDefault();if(e.key==='ArrowLeft')wantedYaw-=.16;if(e.key==='ArrowRight')wantedYaw+=.16;if(e.key==='ArrowUp')wantedPitch=Math.min(1.02,wantedPitch+.1);if(e.key==='ArrowDown')wantedPitch=Math.max(.12,wantedPitch-.1);if(e.key==='+'||e.key==='=')wantedDistance=Math.max(7.7,wantedDistance-.6);if(e.key==='-')wantedDistance=Math.min(18,wantedDistance+.6);if(e.key==='Home')reset()});
 function unlockAudio(){audio?.unlock()}
 function startPurr(){audio?.purr()}
 function reset(){wantedYaw=.24;wantedPitch=.36;wantedDistance=12.4}
 function purr(){petUntil=performance.now()+1800;startPurr()}
 function toggleSound(){return audio?.toggle()||false}
 const headWorld=new T.Vector3(),screen=new T.Vector3();
 function draw(now){frame=requestAnimationFrame(draw);if(!active||document.hidden)return;if(now-lastFrame<1000/45)return;lastFrame=now;yaw+=(wantedYaw-yaw)*.16;pitch+=(wantedPitch-pitch)*.16;distance+=(wantedDistance-distance)*.16;setCamera();const t=now*.001,purring=now<petUntil;canvas.dataset.purring=String(purring);if(head){head.rotation.z=purring&&!reduceMotion?Math.sin(t*10)*.035:0;head.rotation.x=purring?-.06:0;catRoot.scale.y=CAT_SCALE*(reduceMotion?1:1+Math.sin(t*(purring?8:1.8))*(purring?.004:.006));tail.rotation.y=reduceMotion?0:Math.sin(t*(purring?1.5:.65))*.065;eyes.forEach(eye=>eye.scale.y=purring?.3:currentCat?.sick?.45:Math.sin(t*.7)>.995?.08:1);head.getWorldPosition(headWorld);headWorld.y+=.75;screen.copy(headWorld).project(camera);const speech=document.querySelector('#speech');if(speech){speech.style.left=`${(screen.x*.5+.5)*canvas.clientWidth}px`;speech.style.top=`${(-screen.y*.5+.5)*canvas.clientHeight}px`;speech.classList.toggle('purring',purring);if(purring)speech.textContent='Prrrr… that’s the spot. ♡'}}
 const fadeBack=camera.position.z<-2,fadeLeft=camera.position.x<-3;backMat.opacity=fadeBack?.12:1;backMat.depthWrite=!fadeBack;leftMat.opacity=fadeLeft?.12:1;leftMat.depthWrite=!fadeLeft;windowGroup.visible=!fadeBack;print.visible=!fadeBack;renderer.render(scene,camera)}
 resize();frame=requestAnimationFrame(draw);
 return {sync,purr,reset,toggleSound,get soundEnabled(){return audio?.enabled||false},setActive(v){active=v;canvas.tabIndex=v?0:-1},get interacting(){return !!drag},dispose(){cancelAnimationFrame(frame);ro.disconnect();scene.traverse(o=>o.geometry?.dispose());materials.forEach(m=>m.dispose());window.disposeCafeCatMaterials?.();renderer.dispose()}};
